import{c as e,Q as o,j as r,m as d}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"core.md 瘦身與效率研究 — 2026-06-27","description":"","frontmatter":{"date":"2026-06-27T00:00:00.000Z","status":"研究完成，待人工授權執行","method":"內容類型二分 + 逐區塊「移除後在哪犯錯」+ byte 實測 + 下沉落點","scope":"core.md 瘦身與效率研究（六源 byte 貼頂 19,000 後的治本方案）","type":"research / 實證計劃書"},"headers":[],"relativePath":"research/reports/2026-06-27-core-md-slimming-efficiency-study.md","filePath":"research/reports/2026-06-27-core-md-slimming-efficiency-study.md","lastUpdated":1785909234000}'),s={name:"research/reports/2026-06-27-core-md-slimming-efficiency-study.md"};function a(n,t,i,c,l,g){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="core-md-瘦身與效率研究-—-2026-06-27" tabindex="-1">core.md 瘦身與效率研究 — 2026-06-27 <a class="header-anchor" href="#core-md-瘦身與效率研究-—-2026-06-27" aria-label="Permalink to &quot;core.md 瘦身與效率研究 — 2026-06-27&quot;">​</a></h1><h2 id="_0-動機" tabindex="-1">0. 動機 <a class="header-anchor" href="#_0-動機" aria-label="Permalink to &quot;0. 動機&quot;">​</a></h2><p>本日 rewind 補充把六源逼到 <strong>19,000B 貼頂（零餘裕）</strong>，measure --gate 一度 FAIL。pilot-review 已診斷根因：19,000 門檻設定於 content 較少時，現為自然成長壓頂。本研究給 core.md 的<strong>結構性瘦身方案</strong>（非單次 byte 微調），目標騰出真實 headroom 並提升效率。</p><h2 id="_1-核心診斷-core-md-混了兩種內容" tabindex="-1">1. 核心診斷：core.md 混了兩種內容 <a class="header-anchor" href="#_1-核心診斷-core-md-混了兩種內容" aria-label="Permalink to &quot;1. 核心診斷：core.md 混了兩種內容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>類型</th><th>定義</th><th>處置</th></tr></thead><tbody><tr><td><strong>(A) 行為契約</strong></td><td>改變 in-context 行動的鐵律（「遇 X 必 Y」「宣告完成前必跑 Z」）</td><td><strong>留 auto-load</strong></td></tr><tr><td><strong>(B) 參考細節</strong></td><td>命令清單 / 具體數字 / 操作程序 / citation——查得到即可，不需常駐</td><td><strong>下沉 refs，留鐵律句 + 指針</strong></td></tr></tbody></table><p>byte 壓力來自 (B) 在 core.md 累積。<code>README.md</code> 既有「下沉原則」：純參考表/低頻細節 → refs，auto-load 只留鐵律句。core.md 尚未徹底套用此原則。</p><p><strong>效率三維</strong>（「更有效率」的完整定義）：</p><ol><li><strong>byte 效率</strong>（綁定約束）：(B) 下沉 → 騰 headroom，這是 measure --gate 的硬牆。</li><li><strong>compliance 效率</strong>：CLAUDE.md 自陳「規則膨脹後 compliance 急降」——更短 core.md = 更高遵從率，瘦身本身即提升品質，非只省 byte。</li><li><strong>token 效率</strong>（CJK 稅）：core.md CJK-dense（cjk-token-efficiency.md：CJK 2–3× token）。但 byte cap 採 byte 為 canonical 單位正是為對 tokenizer 免疫——故<strong>門檻層面 token 不是約束</strong>；token 效率屬處理成本層，下沉同樣受益。</li></ol><h2 id="_2-逐區塊「移除後在哪犯錯」-byte-實測" tabindex="-1">2. 逐區塊「移除後在哪犯錯」（byte 實測） <a class="header-anchor" href="#_2-逐區塊「移除後在哪犯錯」-byte-實測" aria-label="Permalink to &quot;2. 逐區塊「移除後在哪犯錯」（byte 實測）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>區塊</th><th>byte</th><th>類型</th><th>移除後在哪犯錯？</th><th>裁定</th></tr></thead><tbody><tr><td><strong>L96-97 Git worktree/PR 衝突命令</strong></td><td>385</td><td>(B) 操作程序</td><td>鐵律（多session→worktree、PR衝突不rebase）若留，具體命令 <code>feature.sh wt-start</code>/<code>git show &lt;sha&gt;:&lt;path&gt;</code> 低頻、查得到</td><td><strong>下沉 git-ops ref</strong>，省 ~270B</td></tr><tr><td><strong>L41 量化界線數字</strong></td><td>281</td><td>(B) 具體數字</td><td>鐵律（任務外不自動修）若留，bug≤50/功能≤300/單檔≤500 是軟錨點、低頻</td><td><strong>下沉 the-loop-best-solution</strong>，省 ~210B</td></tr><tr><td><strong>L49 P0 6步流程</strong></td><td>219</td><td>(A)+(B) 混</td><td>細節<strong>已在</strong> the-loop-best-solution（L49 已有指針）；trigger 關鍵詞需留</td><td>微壓 ~40B</td></tr><tr><td><strong>L48 不可逆例外清單</strong></td><td>213</td><td>(A) 關鍵詞辨識</td><td>清單即 trigger 辨識——少了 <code>terraform destroy</code> 等詞可能漏認</td><td><strong>留</strong>（清單有行為價值）</td></tr><tr><td><strong>L59 截斷標示</strong></td><td>103</td><td>(A)</td><td>移除→靜默截斷重現</td><td><strong>留</strong></td></tr><tr><td><strong>L84-85 暫存/Bash 慣例</strong></td><td>250</td><td>(A) 高頻</td><td>本 session 親驗：<code>cd;bash</code> 被 block-dangerous 擋——高頻 safety</td><td><strong>留</strong>（D1/D2/D3/D4 一致）</td></tr></tbody></table><h2 id="_3-推薦執行清單-path-結構下沉-非微調" tabindex="-1">3. 推薦執行清單（Path：結構下沉，非微調） <a class="header-anchor" href="#_3-推薦執行清單-path-結構下沉-非微調" aria-label="Permalink to &quot;3. 推薦執行清單（Path：結構下沉，非微調）&quot;">​</a></h2><p>只動 (B) 類，兩個高價值低風險下沉：</p><p><strong>Sink 1 — Git 操作命令 → 新 <code>.claude/refs/git-ops.md</code></strong>（~270B headroom）</p><ul><li>core.md L96-97 保留鐵律句：「多 session→worktree；commit 用 <code>-- &lt;pathspec&gt;</code>；PR 衝突不 rebase。命令見 <code>git-ops.md</code>」</li><li>下沉：<code>feature.sh wt-start</code> 用法、<code>git show &lt;sha&gt;:&lt;path&gt;</code> 救援程序、<code>-m 必在 -- 前</code> 細節。</li><li>「移除後在哪犯錯」：鐵律保留→決策不變；命令低頻、需要時查 ref。<strong>falsifiable</strong>：<code>grep -q &#39;worktree&#39; core.md</code>（鐵律在）+ <code>grep -q &#39;wt-start&#39; git-ops.md</code>（細節在）+ 六源 −~270B。</li></ul><p><strong>Sink 2 — 量化界線數字 → the-loop-best-solution.md PROPOSE 段</strong>（~210B headroom）</p><ul><li>core.md L41 保留：「任務外 bug/改進記錄回報不自動修；commit 原子性；量化界線見 the-loop-best-solution」</li><li>下沉：bug≤50/功能≤300/單檔≤500 具體數字 + 安全例外細節擇一。</li><li><strong>falsifiable</strong>：<code>grep -q &#39;記錄回報&#39; core.md</code> + <code>grep -qE &#39;≤50|≤300|≤500&#39; the-loop-best-solution.md</code> + 六源 −~210B。</li></ul><p><strong>合計</strong>：六源 19,000 → ~<strong>18,520B</strong>（騰 ~480B 真實 headroom），core.md 9,715 → ~9,235B。兩 sink = 2 個獨立 cycle（≤1 規則檔/cycle，但 sink 改的是 core.md + 1 ref，core.md 為受約束檔，分 2 cycle 各驗）。</p><h2 id="_4-不可動清單-明確標記-防後續誤砍" tabindex="-1">4. 不可動清單（明確標記，防後續誤砍） <a class="header-anchor" href="#_4-不可動清單-明確標記-防後續誤砍" aria-label="Permalink to &quot;4. 不可動清單（明確標記，防後續誤砍）&quot;">​</a></h2><ul><li><strong>Bash 慣例 / 暫存</strong>（L84-85）：高頻 hook 防呆，本 session 親驗。</li><li><strong>不可逆例外清單</strong>（L48）：清單即 trigger 關鍵詞辨識。</li><li><strong>The Loop 六階段序列</strong>（標頭 L3）：canonical 定義錨點。</li><li><strong>各階段鐵律句</strong>（OBSERVE→RECORD 的「遇X必Y」）：行為契約本體。</li><li><strong>wc 量測命令</strong>（L78）：pilot-review 已裁定不可下沉（prompt-lifecycle 純查詢 session 不載入）。</li></ul><h2 id="_5-治理機制-治本-非治標" tabindex="-1">5. 治理機制（治本，非治標） <a class="header-anchor" href="#_5-治理機制-治本-非治標" aria-label="Permalink to &quot;5. 治理機制（治本，非治標）&quot;">​</a></h2><p>pilot D3 建議納入：</p><ul><li><strong>core.md 內容不變式</strong>：新增前先問「這是 (A) 行為契約還是 (B) 參考細節？」(B) 一律進 refs，不進 core.md。寫入 Framework Integrity 作為長期防線。</li><li><strong>90 天門檻重審</strong>（對齊既有「規則=decaying cache 每 14–30 天重審」）：每季對照 content 自然成長重評 19,000 是否仍合理；<strong>重審才上調</strong>（附 eval 實證），非被動撞頂微調。</li><li><strong>不上調 cap 應急</strong>：pilot D4 已否決「為塞規則上調 21,000」=變相放水。</li></ul><h2 id="_6-待人工決策" tabindex="-1">6. 待人工決策 <a class="header-anchor" href="#_6-待人工決策" aria-label="Permalink to &quot;6. 待人工決策&quot;">​</a></h2><ol><li>執行 Sink 1（Git 命令→git-ops.md）+ Sink 2（量化界線→ref）？兩者 ~480B headroom、僅動 (B) 類、各附 falsifiable + healthcheck。</li><li>是否將「core.md (A)/(B) 內容不變式」+ 90 天門檻重審寫入 Framework Integrity（這本身 +~80B，但建立長期防線；可與 Sink 同 cycle 淨負）？</li></ol><p>確認後逐 cycle 走 <code>/autoload-evolution</code>，每 cycle 附 grep + byte + healthcheck 證據。</p>',25)])])}const p=e(s,[["render",a]]);export{m as __pageData,p as default};
